solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 10¹⁸ は Number では正確に表せないので BigInt で読む
const [a, b] = input[0].split(" ").map(BigInt);

// (A + B - 1) / B で切り上げになる（BigInt の割り算は切り捨て）
console.log(((a + b - 1n) / b).toString());
